-- 1. Branding — Formint POS
UPDATE settings SET
    restaurant_name = 'Formint POS',
    address         = '15 Brew Lane, Downtown, Cairo',
    phone           = '+20-100-555-0000',
    email           = 'hello@formintpos.com',
    receipt_footer  = 'Thank you for choosing Formint POS!',
    currency        = 'EGP'
WHERE id = 1;

-- 2. Product images (base64 data URLs)
UPDATE products SET image = CASE id
    WHEN 77 THEN 'data:image/jpeg;base64,'
    WHEN 78 THEN 'data:image/jpeg;base64,'
    WHEN 80 THEN 'data:image/jpeg;base64,'
    WHEN 81 THEN 'data:image/jpeg;base64,'
    WHEN 83 THEN 'data:image/jpeg;base64,'
    WHEN 86 THEN 'data:image/jpeg;base64,'
    WHEN 91 THEN 'data:image/jpeg;base64,'
    WHEN 92 THEN 'data:image/jpeg;base64,'
    WHEN 93 THEN 'data:image/jpeg;base64,'
    WHEN 95 THEN 'data:image/jpeg;base64,'
    WHEN 99 THEN 'data:image/jpeg;base64,'
    WHEN 101 THEN 'data:image/jpeg;base64,'
    WHEN 102 THEN 'data:image/jpeg;base64,'
    WHEN 103 THEN 'data:image/jpeg;base64,'
    ELSE image END
WHERE id IN (77, 78, 80, 81, 83, 86, 91, 92, 93, 95, 99, 101, 102, 103);

-- 3. Categories — Formint colour-coded set (matches the category colour feature)
UPDATE categories SET color = CASE id
    WHEN 17 THEN '#ea580c'
    WHEN 18 THEN '#0f766e'
    WHEN 19 THEN '#b45309'
    WHEN 20 THEN '#7c3aed'
    WHEN 21 THEN '#be123c'
    ELSE color END
WHERE id BETWEEN 17 AND 21;

